    11→// Phase represents the lifecycle stage of a session.
    12→type Phase string
    13→
    14→const (
    15→	PhaseActive Phase = "active"
    16→	PhaseIdle   Phase = "idle"
    17→	PhaseEnded  Phase = "ended"
    18→)
    19→
    20→// allPhases is the canonical list of phases for enumeration (e.g., diagram generation).
    21→var allPhases = []Phase{PhaseIdle, PhaseActive, PhaseEnded}
    22→
    23→// PhaseFromString normalizes a phase string, treating empty or unknown values
    24→// as PhaseIdle for backward compatibility with pre-state-machine session files.
    25→func PhaseFromString(s string) Phase {
    26→	switch Phase(s) {
    27→	case PhaseActive:
    28→		return PhaseActive
    29→	case PhaseIdle:
    30→		return PhaseIdle
    31→	case PhaseEnded:
    32→		return PhaseEnded
    33→	default:
    34→		// Backward compat: unknown phases (including removed "active_committed")
    35→		// normalize to idle.
    36→		return PhaseIdle
    37→	}
    38→}
    39→
    40→// IsActive reports whether the phase represents an active agent turn.
    41→func (p Phase) IsActive() bool {
    42→	return p == PhaseActive
    43→}
    44→
    45→// Event represents something that happened to a session.
    46→type Event int
    47→
    48→const (
    49→	EventTurnStart    Event = iota // Agent begins working on a prompt
    50→	EventTurnEnd                   // Agent finishes its turn
    51→	EventGitCommit                 // A git commit was made (PostCommit hook)
    52→	EventSessionStart              // Session process started (SessionStart hook)
    53→	EventSessionStop               // Session process ended (SessionStop hook)
    54→)
    55→
    56→// allEvents is the canonical list of events for enumeration.
    57→var allEvents = []Event{EventTurnStart, EventTurnEnd, EventGitCommit, EventSessionStart, EventSessionStop}
    58→
    59→// String returns a human-readable name for the event.
    60→func (e Event) String() string {
    61→	switch e {
    62→	case EventTurnStart:
    63→		return "TurnStart"
    64→	case EventTurnEnd:
    65→		return "TurnEnd"
    66→	case EventGitCommit:
    67→		return "GitCommit"
    68→	case EventSessionStart:
    69→		return "SessionStart"
    70→	case EventSessionStop:
    71→		return "SessionStop"
    72→	default:
    73→		return fmt.Sprintf("Event(%d)", int(e))
    74→	}
    75→}
    76→
    77→// Action represents a side effect that should be performed after a transition.
    78→// The caller is responsible for executing these -- the state machine only declares them.
    79→type Action int
    80→
    81→const (
    82→	ActionCondense               Action = iota // Condense session data to permanent storage
    83→	ActionCondenseIfFilesTouched               // Condense only if FilesTouched is non-empty
    84→	ActionDiscardIfNoFiles                     // Discard session if FilesTouched is empty
    85→	ActionWarnStaleSession                     // Warn user about stale session(s)
    86→	ActionClearEndedAt                         // Clear EndedAt timestamp (session re-entering)
    87→	ActionUpdateLastInteraction                // Update LastInteractionTime
    88→)
    89→
    90→// String returns a human-readable name for the action.
    91→func (a Action) String() string {
    92→	switch a {
    93→	case ActionCondense:
    94→		return "Condense"
    95→	case ActionCondenseIfFilesTouched:
    96→		return "CondenseIfFilesTouched"
    97→	case ActionDiscardIfNoFiles:
    98→		return "DiscardIfNoFiles"
    99→	case ActionWarnStaleSession:
   100→		return "WarnStaleSession"
   101→	case ActionClearEndedAt:
   102→		return "ClearEndedAt"
   103→	case ActionUpdateLastInteraction:
   104→		return "UpdateLastInteraction"
   105→	default:
   106→		return fmt.Sprintf("Action(%d)", int(a))
   107→	}
   108→}
   109→
   110→// TransitionContext provides read-only context for transitions that need
   111→// to inspect session state without mutating it.
   112→type TransitionContext struct {
   113→	HasFilesTouched    bool // len(FilesTouched) > 0
   114→	IsRebaseInProgress bool // .git/rebase-merge/ or .git/rebase-apply/ exists
   115→}
   116→
   117→// TransitionResult holds the outcome of a state machine transition.
   118→type TransitionResult struct {
   119→	NewPhase Phase
   120→	Actions  []Action
   121→}
   122→
   123→// Transition computes the next phase and required actions given the current
   124→// phase and an event. This is a pure function with no side effects.
   125→//
   126→// Empty or unknown phase values are normalized to PhaseIdle for backward
   127→// compatibility with session state files created before phase tracking.
   128→func Transition(current Phase, event Event, ctx TransitionContext) TransitionResult {
   129→	// Normalize empty/unknown phase to idle for backward compatibility.
   130→	current = PhaseFromString(string(current))
   131→
   132→	switch current {
   133→	case PhaseIdle:
   134→		return transitionFromIdle(event, ctx)
   135→	case PhaseActive:
   136→		return transitionFromActive(event, ctx)
   137→	case PhaseEnded:
   138→		return transitionFromEnded(event, ctx)
   139→	default:
   140→		// PhaseFromString guarantees we only get known phases, but the
   141→		// exhaustive linter requires handling the default case.
   142→		return TransitionResult{NewPhase: PhaseIdle}
   143→	}
   144→}
   145→
   146→func transitionFromIdle(event Event, ctx TransitionContext) TransitionResult {
   147→	switch event {
   148→	case EventTurnStart:
   149→		return TransitionResult{
   150→			NewPhase: PhaseActive,
   151→			Actions:  []Action{ActionUpdateLastInteraction},
   152→		}
   153→	case EventTurnEnd:
   154→		// Turn end while idle is a no-op (no active turn to end).
   155→		return TransitionResult{NewPhase: PhaseIdle}
   156→	case EventGitCommit:
   157→		if ctx.IsRebaseInProgress {
   158→			return TransitionResult{NewPhase: PhaseIdle}
   159→		}
   160→		return TransitionResult{
   161→			NewPhase: PhaseIdle,
   162→			Actions:  []Action{ActionCondense, ActionUpdateLastInteraction},
   163→		}
   164→	case EventSessionStart:
   165→		// Already condensable, no-op.
   166→		return TransitionResult{NewPhase: PhaseIdle}
   167→	case EventSessionStop:
   168→		return TransitionResult{
   169→			NewPhase: PhaseEnded,
   170→			Actions:  []Action{ActionUpdateLastInteraction},
   171→		}
   172→	default:
   173→		return TransitionResult{NewPhase: PhaseIdle}
   174→	}
   175→}
   176→
   177→func transitionFromActive(event Event, ctx TransitionContext) TransitionResult {
   178→	switch event {
   179→	case EventTurnStart:
   180→		// Ctrl-C recovery: agent crashed or user interrupted mid-turn.
   181→		return TransitionResult{
   182→			NewPhase: PhaseActive,
   183→			Actions:  []Action{ActionUpdateLastInteraction},
   184→		}
   185→	case EventTurnEnd:
   186→		return TransitionResult{
   187→			NewPhase: PhaseIdle,
   188→			Actions:  []Action{ActionUpdateLastInteraction},
   189→		}
   190→	case EventGitCommit:
   191→		if ctx.IsRebaseInProgress {
   192→			return TransitionResult{NewPhase: PhaseActive}
   193→		}
   194→		return TransitionResult{
   195→			NewPhase: PhaseActive,
   196→			Actions:  []Action{ActionCondense, ActionUpdateLastInteraction},
   197→		}
   198→	case EventSessionStart:
   199→		return TransitionResult{
   200→			NewPhase: PhaseActive,
   201→			Actions:  []Action{ActionWarnStaleSession},
   202→		}
   203→	case EventSessionStop:
   204→		return TransitionResult{
   205→			NewPhase: PhaseEnded,
   206→			Actions:  []Action{ActionUpdateLastInteraction},
   207→		}
   208→	default:
   209→		return TransitionResult{NewPhase: PhaseActive}
   210→	}
   211→}
   212→
   213→func transitionFromEnded(event Event, ctx TransitionContext) TransitionResult {
   214→	switch event {
   215→	case EventTurnStart:
   216→		return TransitionResult{
   217→			NewPhase: PhaseActive,
   218→			Actions:  []Action{ActionClearEndedAt, ActionUpdateLastInteraction},
   219→		}
   220→	case EventTurnEnd:
   221→		// Turn end while ended is a no-op.
   222→		return TransitionResult{NewPhase: PhaseEnded}
   223→	case EventGitCommit:
   224→		if ctx.IsRebaseInProgress {
   225→			return TransitionResult{NewPhase: PhaseEnded}
   226→		}
   227→		if ctx.HasFilesTouched {
   228→			return TransitionResult{
   229→				NewPhase: PhaseEnded,
   230→				Actions:  []Action{ActionCondenseIfFilesTouched, ActionUpdateLastInteraction},
   231→			}
   232→		}
   233→		return TransitionResult{
   234→			NewPhase: PhaseEnded,
   235→			Actions:  []Action{ActionDiscardIfNoFiles, ActionUpdateLastInteraction},
   236→		}
   237→	case EventSessionStart:
   238→		return TransitionResult{
   239→			NewPhase: PhaseIdle,
   240→			Actions:  []Action{ActionClearEndedAt},
   241→		}
   242→	case EventSessionStop:
   243→		// Already ended, no-op.
   244→		return TransitionResult{NewPhase: PhaseEnded}
   245→	default:
   246→		return TransitionResult{NewPhase: PhaseEnded}
   247→	}
   248→}
   249→
   250→// ApplyCommonActions applies the common (non-strategy-specific) actions from a
   251→// TransitionResult to the given State. It updates Phase, LastInteractionTime,
   252→// and EndedAt as indicated by the transition.
   253→//
   254→// Returns the subset of actions that require strategy-specific handling
   255→// (e.g., ActionCondense, ActionWarnStaleSession).
   256→// The caller is responsible for dispatching those.
   257→func ApplyCommonActions(state *State, result TransitionResult) []Action {
   258→	state.Phase = result.NewPhase
   259→
   260→	var remaining []Action
   261→	for _, action := range result.Actions {
   262→		switch action {
   263→		case ActionUpdateLastInteraction:
   264→			now := time.Now()
   265→			state.LastInteractionTime = &now
   266→		case ActionClearEndedAt:
   267→			state.EndedAt = nil
   268→		case ActionCondense, ActionCondenseIfFilesTouched, ActionDiscardIfNoFiles,
   269→			ActionWarnStaleSession:
   270→			// Strategy-specific actions — pass through to caller.
   271→			remaining = append(remaining, action)
   272→		}
   273→	}
   274→	return remaining
   275→}
