  1190→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
  1191→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
  1192→	// Get repository config (includes local settings)
  1193→	cfg, err := repo.Config()
  1194→	if err == nil {
  1195→		name = cfg.User.Name
  1196→		email = cfg.User.Email
  1197→	}
  1198→
  1199→	// Provide sensible defaults if git user is not configured
  1200→	if name == "" {
  1201→		name = "Unknown"
  1202→	}
  1203→	if email == "" {
  1204→		email = "unknown@local"
  1205→	}
  1206→
  1207→	return name, email
  1208→}
