  1210→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1211→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1212→// The agentType is used for reassembling chunks in the correct format.
  1213→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1214→	// Collect all transcript-related files
  1215→	var chunkFiles []string
  1216→	var hasBaseFile bool
  1217→
  1218→	for _, entry := range tree.Entries {
  1219→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1220→			hasBaseFile = true
  1221→		}
  1222→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1223→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1224→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1225→			if idx > 0 {
  1226→				chunkFiles = append(chunkFiles, entry.Name)
  1227→			}
  1228→		}
  1229→	}
  1230→
  1231→	// If we have chunk files, read and reassemble them
  1232→	if len(chunkFiles) > 0 {
  1233→		// Sort chunk files by index
  1234→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1235→
  1236→		// Check if base file should be included as chunk 0.
  1237→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1238→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1239→		if hasBaseFile {
  1240→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1241→		}
  1242→
  1243→		var chunks [][]byte
  1244→		for _, chunkFile := range chunkFiles {
  1245→			file, err := tree.File(chunkFile)
  1246→			if err != nil {
  1247→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1248→					slog.String("chunk_file", chunkFile),
  1249→					slog.String("error", err.Error()),
  1250→				)
  1251→				continue
  1252→			}
  1253→			content, err := file.Contents()
  1254→			if err != nil {
  1255→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1256→					slog.String("chunk_file", chunkFile),
  1257→					slog.String("error", err.Error()),
  1258→				)
  1259→				continue
  1260→			}
  1261→			chunks = append(chunks, []byte(content))
  1262→		}
  1263→
  1264→		if len(chunks) > 0 {
  1265→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1266→			if err != nil {
  1267→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1268→			}
  1269→			return result, nil
  1270→		}
  1271→	}
  1272→
  1273→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1274→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1275→		if content, err := file.Contents(); err == nil {
  1276→			return []byte(content), nil
  1277→		}
  1278→	}
  1279→
  1280→	// Try legacy filename
  1281→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1282→		if content, err := file.Contents(); err == nil {
  1283→			return []byte(content), nil
  1284→		}
  1285→	}
  1286→
  1287→	return nil, nil
  1288→}
