  1295→
  1296→// GetCheckpointAuthor retrieves the author of a checkpoint from the entire/checkpoints/v1 commit history.
  1297→// Returns the author of the commit that introduced this checkpoint's metadata.json file.
  1298→// Returns empty Author if the checkpoint is not found or the sessions branch doesn't exist.
  1299→func (s *GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
  1300→	_ = ctx // Reserved for future use
  1301→
  1302→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1303→	ref, err := s.repo.Reference(refName, true)
  1304→	if err != nil {
  1305→		return Author{}, nil
  1306→	}
  1307→
  1308→	// Path to the checkpoint's metadata file
  1309→	metadataPath := checkpointID.Path() + "/" + paths.MetadataFileName
  1310→
  1311→	// Walk commit history looking for the commit that introduced this file
  1312→	iter, err := s.repo.Log(&git.LogOptions{
  1313→		From:  ref.Hash(),
  1314→		Order: git.LogOrderCommitterTime,
  1315→	})
  1316→	if err != nil {
  1317→		return Author{}, nil
  1318→	}
  1319→	defer iter.Close()
