   343→			if content, contentErr := file.Contents(); contentErr == nil {
   344→				fullTranscript = content
   345→			}
   346→		}
   347→	}
   348→
   349→	// Process transcript based on agent type
   350→	if fullTranscript != "" {
   351→		data.Transcript = []byte(fullTranscript)
   352→		data.FullTranscriptLines = countTranscriptItems(agentType, fullTranscript)
   353→		data.Prompts = extractUserPrompts(agentType, fullTranscript)
   354→		data.Context = generateContextFromPrompts(data.Prompts)
   355→	}
   356→
   357→	// Use tracked files from session state (not all files in tree)
   358→	data.FilesTouched = filesTouched
   359→
   360→	// Calculate token usage from the extracted transcript portion
   361→	if len(data.Transcript) > 0 {
   362→		data.TokenUsage = calculateTokenUsage(agentType, data.Transcript, checkpointTranscriptStart)
   363→	}
   364→
   365→	return data, nil
   366→}
   367→
   368→// countTranscriptItems counts lines (JSONL) or messages (JSON) in a transcript.
   369→// For Claude Code and JSONL-based agents, this counts lines.
   370→// For Gemini CLI and JSON-based agents, this counts messages.
   371→// Returns 0 if the content is empty or malformed.
   372→func countTranscriptItems(agentType agent.AgentType, content string) int {
   373→	if content == "" {
   374→		return 0
   375→	}
   376→
   377→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
   378→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
   379→		transcript, err := geminicli.ParseTranscript([]byte(content))
   380→		if err == nil && transcript != nil && len(transcript.Messages) > 0 {
   381→			return len(transcript.Messages)
   382→		}
   383→		// If agentType is explicitly Gemini but parsing failed, return 0
   384→		if agentType == agent.AgentTypeGemini {
   385→			return 0
   386→		}
   387→		// Otherwise fall through to JSONL parsing for Unknown type
   388→	}
   389→
   390→	// Claude Code and other JSONL-based agents
   391→	allLines := strings.Split(content, "\n")
   392→	// Trim trailing empty lines (from final \n in JSONL)
   393→	for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
   394→		allLines = allLines[:len(allLines)-1]
   395→	}
   396→	return len(allLines)
   397→}
   398→
   399→// extractUserPrompts extracts all user prompts from transcript content.
   400→// Returns prompts with IDE context tags stripped (e.g., <ide_opened_file>).
   401→func extractUserPrompts(agentType agent.AgentType, content string) []string {
   402→	if content == "" {
   403→		return nil
   404→	}
   405→
   406→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
   407→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
   408→		prompts, err := geminicli.ExtractAllUserPrompts([]byte(content))
   409→		if err == nil && len(prompts) > 0 {
   410→			// Strip IDE context tags for consistency with Claude Code handling
   411→			cleaned := make([]string, 0, len(prompts))
   412→			for _, prompt := range prompts {
   413→				if stripped := textutil.StripIDEContextTags(prompt); stripped != "" {
   414→					cleaned = append(cleaned, stripped)
   415→				}
   416→			}
   417→			return cleaned
   418→		}
   419→		// If agentType is explicitly Gemini but parsing failed, return nil
   420→		if agentType == agent.AgentTypeGemini {
   421→			return nil
   422→		}
   423→		// Otherwise fall through to JSONL parsing for Unknown type
   424→	}
   425→
   426→	// Claude Code and other JSONL-based agents
   427→	return extractUserPromptsFromLines(strings.Split(content, "\n"))
   428→}
